changeSet.sql:
DO $do$ DECLARE actor CONSTANT TEXT := 'di-access-menu-v2'; marker_created CONSTANT TEXT := 'di-access-created'; marker_aligned CONSTANT TEXT := 'di-access-aligned'; marker_source CONSTANT TEXT := 'di-access-source'; marker_direct CONSTANT TEXT := 'di-access-direct'; marker_retired CONSTANT TEXT := 'di-access-retired'; resource_id BIGINT; resource_root_count INTEGER; legacy_sources_id BIGINT; existing_overview_id BIGINT; existing_overview_was_created BOOLEAN; access_overview_id BIGINT; runtime_id BIGINT; runtime_was_created BOOLEAN; target_menu_id BIGINT; target_was_direct BOOLEAN; target_was_created BOOLEAN; source_menu_ids BIGINT[] := ARRAY[]::BIGINT[]; ingestion_menu_ids BIGINT[] := ARRAY[]::BIGINT[]; metadata_menu_ids BIGINT[] := ARRAY[]::BIGINT[]; changes_menu_ids BIGINT[] := ARRAY[]::BIGINT[]; runtime_menu_ids BIGINT[] := ARRAY[]::BIGINT[]; connector_menu_ids BIGINT[] := ARRAY[]::BIGINT[]; jdbc_menu_ids BIGINT[] := ARRAY[]::BIGINT[]; desired RECORD; seed_hash CONSTANT TEXT := 'd3283387b18e31a492acd664233a201e5b84bcb3ab044485f8c8d8becef74283'; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('dts:portal-menu:access-convergence:20260801-01', 0));
IF EXISTS ( SELECT 1 FROM portal_menu WHERE metadata IS NOT NULL AND NOT pg_input_is_valid(metadata, 'jsonb') ) THEN RAISE EXCEPTION 'data-integration menu metadata contains invalid JSON; convergence aborted'; END IF;
CREATE TABLE IF NOT EXISTS portal_menu_di_access_snapshot_20260801 ( menu_id BIGINT PRIMARY KEY, name TEXT NOT NULL, path TEXT, component TEXT, sort_order INTEGER, metadata TEXT, parent_id BIGINT, icon TEXT, security_level TEXT, deleted BOOLEAN NOT NULL, last_modified_by TEXT, last_modified_date TIMESTAMP, snapshot_owner VARCHAR(50) NOT NULL ); CREATE TABLE IF NOT EXISTS portal_seed_di_access_snapshot_20260801 ( singleton BOOLEAN PRIMARY KEY CHECK (singleton), config_existed BOOLEAN NOT NULL, cfg_value VARCHAR(2000), description TEXT, category TEXT, sensitive BOOLEAN, data_type TEXT, editable BOOLEAN, sort_order INTEGER, display_name TEXT, config_scope TEXT, restart_required BOOLEAN, owner TEXT, created_by VARCHAR(50), created_date TIMESTAMP, last_modified_by VARCHAR(50), last_modified_date TIMESTAMP, menu_snapshot_count INTEGER NOT NULL DEFAULT 0, snapshot_owner VARCHAR(50) NOT NULL );
IF EXISTS (SELECT 1 FROM portal_menu_di_access_snapshot_20260801) OR EXISTS (SELECT 1 FROM portal_seed_di_access_snapshot_20260801) THEN RAISE EXCEPTION 'data-integration menu convergence snapshot already exists'; END IF;
IF EXISTS (SELECT 1 FROM system_config WHERE cfg_key = 'portal.menu.seed.hash') THEN INSERT INTO portal_seed_di_access_snapshot_20260801 ( singleton, config_existed, cfg_value, description, category, sensitive, data_type, editable, sort_order, display_name, config_scope, restart_required, owner, created_by, created_date, last_modified_by, last_modified_date, snapshot_owner ) SELECT TRUE, TRUE, cfg_value, description, category, sensitive, data_type, editable, sort_order, display_name, config_scope, restart_required, owner, created_by, created_date, last_modified_by, last_modified_date, actor FROM system_config WHERE cfg_key = 'portal.menu.seed.hash'; ELSE INSERT INTO portal_seed_di_access_snapshot_20260801 ( singleton, config_existed, snapshot_owner ) VALUES (TRUE, FALSE, actor); END IF;
SELECT COUNT(*), MIN(id) INTO resource_root_count, resource_id FROM portal_menu WHERE parent_id IS NULL AND deleted = FALSE AND metadata IS NOT NULL AND metadata::jsonb ->> 'key' = 'resource';
IF resource_root_count = 0 THEN IF EXISTS (SELECT 1 FROM portal_menu) THEN RAISE EXCEPTION 'data-integration menu root metadata key resource is missing'; END IF; -- Keep the zero-row manifest so rollback can distinguish a valid empty-tree apply. RETURN; END IF; IF resource_root_count <> 1 THEN RAISE EXCEPTION 'data-integration menu root metadata key resource is ambiguous: % rows', resource_root_count; END IF;
SELECT COALESCE(ARRAY_AGG(id ORDER BY id), ARRAY[]::BIGINT[]) INTO runtime_menu_ids FROM portal_menu WHERE parent_id = resource_id AND ( deleted = FALSE OR (deleted = TRUE AND created_by = actor AND last_modified_by = 'di-access-rollback') ) AND ( name = 'sys.nav.portal.resourceRuntime' OR metadata::jsonb ->> 'titleKey' = 'sys.nav.portal.resourceRuntime' );
SELECT id, created_by = actor INTO runtime_id, runtime_was_created FROM portal_menu WHERE id = ANY(runtime_menu_ids) ORDER BY CASE WHEN deleted = FALSE THEN 0 ELSE 1 END, id LIMIT 1;
SELECT COALESCE(ARRAY_AGG(id ORDER BY id), ARRAY[]::BIGINT[]) INTO source_menu_ids FROM portal_menu WHERE parent_id = resource_id AND deleted = FALSE AND (name = 'sys.nav.portal.resourceSources' OR metadata::jsonb ->> 'titleKey' = 'sys.nav.portal.resourceSources'); SELECT COALESCE(ARRAY_AGG(id ORDER BY id), ARRAY[]::BIGINT[]) INTO ingestion_menu_ids FROM portal_menu WHERE parent_id = resource_id AND deleted = FALSE AND (name = 'sys.nav.portal.resourceIngestion' OR metadata::jsonb ->> 'titleKey' = 'sys.nav.portal.resourceIngestion'); SELECT COALESCE(ARRAY_AGG(id ORDER BY id), ARRAY[]::BIGINT[]) INTO metadata_menu_ids FROM portal_menu WHERE parent_id = resource_id AND deleted = FALSE AND (name = 'sys.nav.portal.resourceMetadata' OR metadata::jsonb ->> 'titleKey' = 'sys.nav.portal.resourceMetadata'); SELECT COALESCE(ARRAY_AGG(id ORDER BY id), ARRAY[]::BIGINT[]) INTO changes_menu_ids FROM portal_menu WHERE parent_id = resource_id AND deleted = FALSE AND (name = 'sys.nav.portal.resourceChanges' OR metadata::jsonb ->> 'titleKey' = 'sys.nav.portal.resourceChanges'); SELECT COALESCE(ARRAY_AGG(id ORDER BY id), ARRAY[]::BIGINT[]) INTO connector_menu_ids FROM portal_menu WHERE deleted = FALSE AND (parent_id = resource_id OR parent_id = ANY(runtime_menu_ids)) AND (name = 'sys.nav.portal.resourceConnectors' OR metadata::jsonb ->> 'titleKey' = 'sys.nav.portal.resourceConnectors'); SELECT COALESCE(ARRAY_AGG(id ORDER BY id), ARRAY[]::BIGINT[]) INTO jdbc_menu_ids FROM portal_menu WHERE deleted = FALSE AND (parent_id = resource_id OR parent_id = ANY(runtime_menu_ids)) AND (name = 'sys.nav.portal.resourceJdbcDrivers' OR metadata::jsonb ->> 'titleKey' = 'sys.nav.portal.resourceJdbcDrivers');
-- One row per menu avoids the bounded system_config cfg_value column and supports exact restore. INSERT INTO portal_menu_di_access_snapshot_20260801 ( menu_id, name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, last_modified_by, last_modified_date, snapshot_owner ) SELECT menu.id, menu.name, menu.path, menu.component, menu.sort_order, menu.metadata, menu.parent_id, menu.icon, menu.security_level, menu.deleted, menu.last_modified_by, menu.last_modified_date, actor FROM portal_menu menu WHERE menu.created_by IS DISTINCT FROM actor AND (menu.parent_id = resource_id OR menu.parent_id = ANY(runtime_menu_ids)) AND ( menu.name IN ( 'sys.nav.portal.resourceSources', 'sys.nav.portal.resourceIngestion', 'sys.nav.portal.resourceMetadata', 'sys.nav.portal.resourceChanges', 'sys.nav.portal.resourceAccessOverview', 'sys.nav.portal.resourceDatabaseAccess', 'sys.nav.portal.resourceApiAccess', 'sys.nav.portal.resourceFileAccess', 'sys.nav.portal.resourceAccessDefaults', 'sys.nav.portal.resourceRuntime', 'sys.nav.portal.resourceConnectors', 'sys.nav.portal.resourceJdbcDrivers' ) OR menu.metadata::jsonb ->> 'titleKey' IN ( 'sys.nav.portal.resourceSources', 'sys.nav.portal.resourceIngestion', 'sys.nav.portal.resourceMetadata', 'sys.nav.portal.resourceChanges', 'sys.nav.portal.resourceAccessOverview', 'sys.nav.portal.resourceDatabaseAccess', 'sys.nav.portal.resourceApiAccess', 'sys.nav.portal.resourceFileAccess', 'sys.nav.portal.resourceAccessDefaults', 'sys.nav.portal.resourceRuntime', 'sys.nav.portal.resourceConnectors', 'sys.nav.portal.resourceJdbcDrivers' ) );
SELECT id INTO legacy_sources_id FROM portal_menu WHERE id = ANY(source_menu_ids) ORDER BY id LIMIT 1;
SELECT id, created_by = actor INTO existing_overview_id, existing_overview_was_created FROM portal_menu WHERE parent_id = resource_id AND ( deleted = FALSE OR (deleted = TRUE AND created_by = actor AND last_modified_by = 'di-access-rollback') ) AND ( name = 'sys.nav.portal.resourceAccessOverview' OR metadata::jsonb ->> 'titleKey' = 'sys.nav.portal.resourceAccessOverview' ) ORDER BY CASE WHEN deleted = FALSE THEN 0 ELSE 1 END, id LIMIT 1;
access_overview_id := COALESCE(legacy_sources_id, existing_overview_id); IF access_overview_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.resourceAccessOverview', 'resource/access-overview', '/pages/foundation/access/AccessWorkspacePage', 1, '{"key":"accessOverview","sectionKey":"resource","entryKey":"accessOverview","titleKey":"sys.nav.portal.resourceAccessOverview","title":"接入概览","icon":"solar:layers-bold-duotone","externalLink":"/foundation/data-sources"}', resource_id, 'solar:layers-bold-duotone', 'GENERAL', FALSE, actor, now(), marker_created, now() ) RETURNING id INTO access_overview_id; ELSE UPDATE portal_menu SET name = 'sys.nav.portal.resourceAccessOverview', path = 'resource/access-overview', component = '/pages/foundation/access/AccessWorkspacePage', sort_order = 1, metadata = '{"key":"accessOverview","sectionKey":"resource","entryKey":"accessOverview","titleKey":"sys.nav.portal.resourceAccessOverview","title":"接入概览","icon":"solar:layers-bold-duotone","externalLink":"/foundation/data-sources"}', icon = 'solar:layers-bold-duotone', deleted = FALSE, last_modified_by = CASE WHEN legacy_sources_id IS NOT NULL THEN marker_source WHEN existing_overview_was_created THEN marker_created ELSE marker_aligned END, last_modified_date = now() WHERE id = access_overview_id; END IF;
INSERT INTO portal_menu_visibility ( id, menu_id, role_code, permission_code, data_level, created_by, created_date, last_modified_by, last_modified_date ) SELECT nextval('portal_menu_visibility_seq'), access_overview_id, source.role_code, source.permission_code, source.data_level, actor, now(), actor, now() FROM ( SELECT DISTINCT visibility.role_code, visibility.permission_code, visibility.data_level FROM portal_menu_visibility visibility WHERE visibility.menu_id = ANY( source_menu_ids || ingestion_menu_ids || metadata_menu_ids || changes_menu_ids ) ) source WHERE NOT EXISTS ( SELECT 1 FROM portal_menu_visibility target WHERE target.menu_id = access_overview_id AND target.role_code = source.role_code AND target.permission_code IS NOT DISTINCT FROM source.permission_code AND target.data_level IS NOT DISTINCT FROM source.data_level );
UPDATE portal_menu SET deleted = TRUE, last_modified_by = marker_retired, last_modified_date = now() WHERE id = existing_overview_id AND existing_overview_id IS DISTINCT FROM access_overview_id AND deleted = FALSE;
-- Database/API/file inherit Sources + Ingestion. Defaults intentionally inherits nothing. FOR desired IN SELECT * FROM (VALUES ('databaseAccess', 'database-access', 'sys.nav.portal.resourceDatabaseAccess', '数据库接入', 'solar:database-bold-duotone', '/foundation/data-sources/database', '/pages/foundation/access/AccessWorkspacePage', 2), ('apiAccess', 'api-access', 'sys.nav.portal.resourceApiAccess', 'API 接入', 'solar:link-bold-duotone', '/foundation/data-sources/api', '/pages/foundation/access/AccessWorkspacePage', 3), ('fileAccess', 'file-access', 'sys.nav.portal.resourceFileAccess', '离线文件接入', 'solar:file-text-bold-duotone', '/foundation/data-sources/files', '/pages/foundation/access/AccessWorkspacePage', 4), ('accessDefaults', 'access-defaults', 'sys.nav.portal.resourceAccessDefaults', '默认策略', 'solar:settings-minimalistic-bold-duotone', '/foundation/data-sources/defaults', '/pages/foundation/access/AccessDefaultsPage', 5) ) AS access_node(menu_key, path_segment, title_key, menu_title, menu_icon, external_link, component_path, menu_order) LOOP target_menu_id := NULL; target_was_created := FALSE; SELECT id, created_by = actor INTO target_menu_id, target_was_created FROM portal_menu WHERE parent_id = resource_id AND ( deleted = FALSE OR (deleted = TRUE AND created_by = actor AND last_modified_by = 'di-access-rollback') ) AND (name = desired.title_key OR metadata::jsonb ->> 'titleKey' = desired.title_key) ORDER BY CASE WHEN deleted = FALSE THEN 0 ELSE 1 END, id LIMIT 1;
IF target_menu_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( desired.title_key, 'resource/' || desired.path_segment, desired.component_path, desired.menu_order, jsonb_build_object( 'key', desired.menu_key, 'sectionKey', 'resource', 'entryKey', desired.menu_key, 'titleKey', desired.title_key, 'title', desired.menu_title, 'icon', desired.menu_icon, 'externalLink', desired.external_link )::TEXT, resource_id, desired.menu_icon, 'GENERAL', FALSE, actor, now(), marker_created, now() ) RETURNING id INTO target_menu_id; ELSE UPDATE portal_menu SET name = desired.title_key, path = 'resource/' || desired.path_segment, component = desired.component_path, sort_order = desired.menu_order, metadata = jsonb_build_object( 'key', desired.menu_key, 'sectionKey', 'resource', 'entryKey', desired.menu_key, 'titleKey', desired.title_key, 'title', desired.menu_title, 'icon', desired.menu_icon, 'externalLink', desired.external_link )::TEXT, icon = desired.menu_icon, deleted = FALSE, last_modified_by = CASE WHEN target_was_created THEN marker_created ELSE marker_aligned END, last_modified_date = now() WHERE id = target_menu_id; END IF;
IF desired.menu_key <> 'accessDefaults' THEN INSERT INTO portal_menu_visibility ( id, menu_id, role_code, permission_code, data_level, created_by, created_date, last_modified_by, last_modified_date ) SELECT nextval('portal_menu_visibility_seq'), target_menu_id, source.role_code, source.permission_code, source.data_level, actor, now(), actor, now() FROM ( SELECT DISTINCT visibility.role_code, visibility.permission_code, visibility.data_level FROM portal_menu_visibility visibility WHERE visibility.menu_id = ANY(source_menu_ids || ingestion_menu_ids) AND visibility.created_by IS DISTINCT FROM actor ) source WHERE NOT EXISTS ( SELECT 1 FROM portal_menu_visibility target WHERE target.menu_id = target_menu_id AND target.role_code = source.role_code AND target.permission_code IS NOT DISTINCT FROM source.permission_code AND target.data_level IS NOT DISTINCT FROM source.data_level ); END IF; END LOOP;
IF runtime_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'sys.nav.portal.resourceRuntime', 'resource/runtime', NULL, 6, '{"key":"runtime","sectionKey":"resource","entryKey":"runtime","titleKey":"sys.nav.portal.resourceRuntime","title":"连接器与运行时","icon":"solar:widget-add-bold-duotone"}', resource_id, 'solar:widget-add-bold-duotone', 'GENERAL', FALSE, actor, now(), marker_created, now() ) RETURNING id INTO runtime_id; runtime_was_created := TRUE; runtime_menu_ids := array_append(runtime_menu_ids, runtime_id); ELSE UPDATE portal_menu SET name = 'sys.nav.portal.resourceRuntime', path = 'resource/runtime', component = NULL, sort_order = 6, metadata = '{"key":"runtime","sectionKey":"resource","entryKey":"runtime","titleKey":"sys.nav.portal.resourceRuntime","title":"连接器与运行时","icon":"solar:widget-add-bold-duotone"}', icon = 'solar:widget-add-bold-duotone', deleted = FALSE, last_modified_by = CASE WHEN runtime_was_created THEN marker_created ELSE marker_aligned END, last_modified_date = now() WHERE id = runtime_id; END IF;
-- Merge every duplicate Runtime visibility triple into the deterministic canonical row. INSERT INTO portal_menu_visibility ( id, menu_id, role_code, permission_code, data_level, created_by, created_date, last_modified_by, last_modified_date ) SELECT nextval('portal_menu_visibility_seq'), runtime_id, source.role_code, source.permission_code, source.data_level, actor, now(), actor, now() FROM ( SELECT DISTINCT visibility.role_code, visibility.permission_code, visibility.data_level FROM portal_menu_visibility visibility JOIN portal_menu runtime_source ON runtime_source.id = visibility.menu_id WHERE runtime_source.id = ANY(runtime_menu_ids) AND runtime_source.deleted = FALSE ) source WHERE NOT EXISTS ( SELECT 1 FROM portal_menu_visibility target WHERE target.menu_id = runtime_id AND target.role_code = source.role_code AND target.permission_code IS NOT DISTINCT FROM source.permission_code AND target.data_level IS NOT DISTINCT FROM source.data_level );
UPDATE portal_menu SET deleted = TRUE, last_modified_by = marker_retired, last_modified_date = now() WHERE id = ANY(runtime_menu_ids) AND id <> runtime_id AND deleted = FALSE;
-- Connectors and JDBC retain the union of their own historical visibility triples. FOR desired IN SELECT * FROM (VALUES ('connectors', 'sys.nav.portal.resourceConnectors', '连接器目录', 'solar:widget-add-bold-duotone', '/foundation/connectors', '/pages/foundation/ConnectorRegistryPage', 1), ('jdbcDrivers', 'sys.nav.portal.resourceJdbcDrivers', '驱动管理', 'solar:plug-circle-bold-duotone', '/foundation/jdbc-drivers', '/pages/foundation/JdbcDriversPage', 2) ) AS runtime_node(menu_key, title_key, menu_title, menu_icon, external_link, component_path, menu_order) LOOP target_menu_id := NULL; target_was_direct := FALSE; target_was_created := FALSE; SELECT id, parent_id = resource_id, created_by = actor INTO target_menu_id, target_was_direct, target_was_created FROM portal_menu WHERE (parent_id = resource_id OR parent_id = ANY(runtime_menu_ids)) AND ( deleted = FALSE OR (deleted = TRUE AND created_by = actor AND last_modified_by = 'di-access-rollback') ) AND (name = desired.title_key OR metadata::jsonb ->> 'titleKey' = desired.title_key) ORDER BY CASE WHEN deleted = FALSE THEN 0 ELSE 1 END, CASE WHEN parent_id = resource_id THEN 0 ELSE 1 END, id LIMIT 1;
IF target_menu_id IS NULL THEN INSERT INTO portal_menu ( name, path, component, sort_order, metadata, parent_id, icon, security_level, deleted, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( desired.title_key, 'resource/runtime/' || CASE WHEN desired.menu_key = 'jdbcDrivers' THEN 'jdbc-drivers' ELSE desired.menu_key END, desired.component_path, desired.menu_order, jsonb_build_object( 'key', desired.menu_key, 'sectionKey', 'resource', 'entryKey', desired.menu_key, 'titleKey', desired.title_key, 'title', desired.menu_title, 'icon', desired.menu_icon, 'externalLink', desired.external_link )::TEXT, runtime_id, desired.menu_icon, 'GENERAL', FALSE, actor, now(), marker_created, now() ) RETURNING id INTO target_menu_id; ELSE UPDATE portal_menu SET parent_id = runtime_id, name = desired.title_key, path = 'resource/runtime/' || CASE WHEN desired.menu_key = 'jdbcDrivers' THEN 'jdbc-drivers' ELSE desired.menu_key END, component = desired.component_path, sort_order = desired.menu_order, metadata = jsonb_build_object( 'key', desired.menu_key, 'sectionKey', 'resource', 'entryKey', desired.menu_key, 'titleKey', desired.title_key, 'title', desired.menu_title, 'icon', desired.menu_icon, 'externalLink', desired.external_link )::TEXT, icon = desired.menu_icon, deleted = FALSE, last_modified_by = CASE WHEN target_was_created THEN marker_created WHEN target_was_direct THEN marker_direct ELSE marker_aligned END, last_modified_date = now() WHERE id = target_menu_id; END IF;
INSERT INTO portal_menu_visibility ( id, menu_id, role_code, permission_code, data_level, created_by, created_date, last_modified_by, last_modified_date ) SELECT nextval('portal_menu_visibility_seq'), target_menu_id, source.role_code, source.permission_code, source.data_level, actor, now(), actor, now() FROM ( SELECT DISTINCT visibility.role_code, visibility.permission_code, visibility.data_level FROM portal_menu_visibility visibility WHERE visibility.menu_id = ANY( CASE WHEN desired.menu_key = 'connectors' THEN connector_menu_ids ELSE jdbc_menu_ids END ) ) source WHERE NOT EXISTS ( SELECT 1 FROM portal_menu_visibility target WHERE target.menu_id = target_menu_id AND target.role_code = source.role_code AND target.permission_code IS NOT DISTINCT FROM source.permission_code AND target.data_level IS NOT DISTINCT FROM source.data_level );
UPDATE portal_menu SET deleted = TRUE, last_modified_by = marker_retired, last_modified_date = now() WHERE id <> target_menu_id AND (parent_id = resource_id OR parent_id = ANY(runtime_menu_ids)) AND deleted = FALSE AND (name = desired.title_key OR metadata::jsonb ->> 'titleKey' = desired.title_key); END LOOP;
UPDATE portal_menu SET deleted = TRUE, last_modified_by = marker_retired, last_modified_date = now() WHERE parent_id = resource_id AND id <> access_overview_id AND deleted = FALSE AND ( name IN ( 'sys.nav.portal.resourceSources', 'sys.nav.portal.resourceMetadata', 'sys.nav.portal.resourceIngestion', 'sys.nav.portal.resourceChanges' ) OR metadata::jsonb ->> 'titleKey' IN ( 'sys.nav.portal.resourceSources', 'sys.nav.portal.resourceMetadata', 'sys.nav.portal.resourceIngestion', 'sys.nav.portal.resourceChanges' ) );
UPDATE portal_seed_di_access_snapshot_20260801 SET menu_snapshot_count = ( SELECT COUNT(*) FROM portal_menu_di_access_snapshot_20260801 WHERE snapshot_owner = actor ) WHERE singleton = TRUE AND snapshot_owner = actor;
-- Prevent a seed-hash mismatch from invoking the service's destructive unseeded path. IF EXISTS (SELECT 1 FROM system_config WHERE cfg_key = 'portal.menu.seed.hash') THEN UPDATE system_config SET cfg_value = seed_hash, description = COALESCE(NULLIF(description, ''), 'Portal menu seed hash'), last_modified_by = actor, last_modified_date = now() WHERE cfg_key = 'portal.menu.seed.hash'; ELSE INSERT INTO system_config ( cfg_key, cfg_value, description, category, sensitive, data_type, editable, sort_order, display_name, config_scope, restart_required, owner, created_by, created_date, last_modified_by, last_modified_date ) VALUES ( 'portal.menu.seed.hash', seed_hash, 'Portal menu seed hash', 'SYSTEM', FALSE, 'STRING', FALSE, 0, 'Portal menu seed hash', 'RUNTIME', FALSE, 'platform', actor, now(), actor, now() ); END IF; END $do$;

rollback.sql:
DO $do$
DECLARE
    actor CONSTANT TEXT := 'di-access-menu-v2';
    marker_rollback CONSTANT TEXT := 'di-access-rollback';
    resource_id BIGINT;
    resource_root_count INTEGER;
    expected_snapshot_count INTEGER;
    seed_existed BOOLEAN;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('dts:portal-menu:access-convergence:20260801-01', 0));

    IF to_regclass(format('%I.%I', current_schema(), 'portal_menu_di_access_snapshot_20260801')) IS NULL
        OR to_regclass(format('%I.%I', current_schema(), 'portal_seed_di_access_snapshot_20260801')) IS NULL THEN
        RAISE EXCEPTION 'data-integration menu convergence rollback snapshot is missing';
    END IF;

    SELECT menu_snapshot_count, config_existed
      INTO expected_snapshot_count, seed_existed
      FROM portal_seed_di_access_snapshot_20260801
     WHERE singleton = TRUE AND snapshot_owner = actor;
    IF NOT FOUND OR expected_snapshot_count <> (
        SELECT COUNT(*) FROM portal_menu_di_access_snapshot_20260801
         WHERE snapshot_owner = actor
    ) THEN
        RAISE EXCEPTION 'data-integration menu convergence rollback snapshot is missing or incomplete';
    END IF;

    IF EXISTS (
        SELECT 1 FROM portal_menu
         WHERE metadata IS NOT NULL
           AND NOT pg_input_is_valid(metadata, 'jsonb')
    ) THEN
        RAISE EXCEPTION 'data-integration menu metadata contains invalid JSON; rollback aborted';
    END IF;

    SELECT COUNT(*), MIN(id)
      INTO resource_root_count, resource_id
      FROM portal_menu
     WHERE parent_id IS NULL
       AND deleted = FALSE
       AND metadata IS NOT NULL
       AND metadata::jsonb ->> 'key' = 'resource';
    IF resource_root_count = 0 THEN
        IF EXISTS (SELECT 1 FROM portal_menu) THEN
            RAISE EXCEPTION 'data-integration menu root metadata key resource is missing during rollback';
        END IF;
    ELSIF resource_root_count <> 1 THEN
        RAISE EXCEPTION 'data-integration menu root metadata key resource is ambiguous during rollback: % rows', resource_root_count;
    END IF;

    DELETE FROM portal_menu_visibility WHERE created_by = actor;

    UPDATE portal_menu menu
       SET name = snapshot.name,
           path = snapshot.path,
           component = snapshot.component,
           sort_order = snapshot.sort_order,
           metadata = snapshot.metadata,
           parent_id = snapshot.parent_id,
           icon = snapshot.icon,
           security_level = snapshot.security_level,
           deleted = snapshot.deleted,
           last_modified_by = snapshot.last_modified_by,
           last_modified_date = snapshot.last_modified_date
      FROM portal_menu_di_access_snapshot_20260801 snapshot
     WHERE menu.id = snapshot.menu_id
       AND snapshot.snapshot_owner = actor;

    UPDATE portal_menu
       SET deleted = TRUE, last_modified_by = marker_rollback, last_modified_date = now()
     WHERE created_by = actor;

    IF seed_existed THEN
        INSERT INTO system_config (
            cfg_key, cfg_value, description, category, sensitive, data_type, editable, sort_order,
            display_name, config_scope, restart_required, owner, created_by, created_date,
            last_modified_by, last_modified_date
        )
        SELECT 'portal.menu.seed.hash', cfg_value, description, category, sensitive, data_type,
               editable, sort_order, display_name, config_scope, restart_required, owner,
               created_by, created_date, last_modified_by, last_modified_date
          FROM portal_seed_di_access_snapshot_20260801
         WHERE singleton = TRUE AND snapshot_owner = actor
        ON CONFLICT (cfg_key) DO UPDATE
            SET cfg_value = EXCLUDED.cfg_value,
                description = EXCLUDED.description,
                category = EXCLUDED.category,
                sensitive = EXCLUDED.sensitive,
                data_type = EXCLUDED.data_type,
                editable = EXCLUDED.editable,
                sort_order = EXCLUDED.sort_order,
                display_name = EXCLUDED.display_name,
                config_scope = EXCLUDED.config_scope,
                restart_required = EXCLUDED.restart_required,
                owner = EXCLUDED.owner,
                created_by = EXCLUDED.created_by,
                created_date = EXCLUDED.created_date,
                last_modified_by = EXCLUDED.last_modified_by,
                last_modified_date = EXCLUDED.last_modified_date;
    ELSE
        DELETE FROM system_config WHERE cfg_key = 'portal.menu.seed.hash';
    END IF;

    DROP TABLE portal_menu_di_access_snapshot_20260801;
    DROP TABLE portal_seed_di_access_snapshot_20260801;
END
$do$;
